self.KB_CONTENT["card:758036"]={"id":"card:758036","ty":"card","sourceId":"758036","title":"『申報書媒體資料產生作業』中的『選擇開業日期、計算調整稅額並回填十二月份營業稅申報書』為何？","ver":"iGP","topic":"營業稅","keywords":["營業稅","稅額","年度","申報"],"y":"other","answer":"* 為兼營營業人於年度調整營業稅額專用。 延伸閱讀 WF營業稅流程解析說明 延伸閱讀 WF申報書媒體資料產生作業","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
