self.KB_CONTENT["card:751981"]={"id":"card:751981","ty":"card","sourceId":"751981","title":"『會計傳票建立作業』中的『原幣金額 (TB015)』為何？","ver":"iGP","topic":"傳票","keywords":["傳票","交易","原幣"],"y":"other","answer":"* 輸入本次交易的金額。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
