self.KB_CONTENT["field:778434"]={"id":"field:778434","ty":"field","sourceId":"778434","title":".領料方式","ver":"GP4以上","topic":"","keywords":[],"job":"領料單自動產生作業","code":"","answer":"* 產生領料單的產生方式。* 分為1.成套領料、2.補足已領套數及3.補足需領量。預設1.成套領料。","file":"fields.jsonl"};
